CREATE OR ALTER PROCEDURE dw.sp_ETL_ConsolidarCierreERP
    @PeriodoFiscal CHAR(7) -- Ejemplo: '2023-12'
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;

    -- 1. Integración de asientos contables desde SAP S/4HANA y Microsoft Dynamics 365
    MERGE INTO dw.Fact_Finanzas_Consolidado AS Target
    USING (
        SELECT AsientoID, OrigenERP, CentroCostoID, CuentaContable, MontoDOP, FechaContable
        FROM staging.vw_Unificada_SAP_Dynamics_Oracle
        WHERE PeriodoFiscal = @PeriodoFiscal
    ) AS Source
    ON (Target.AsientoID = Source.AsientoID AND Target.OrigenERP = Source.OrigenERP)
    WHEN MATCHED THEN
        UPDATE SET Target.MontoDOP = Source.MontoDOP, Target.FechaActualizacion = SYSDATETIME()
    WHEN NOT MATCHED THEN
        INSERT (AsientoID, OrigenERP, CentroCostoID, CuentaContable, MontoDOP, FechaContable, FechaActualizacion)
        VALUES (Source.AsientoID, Source.OrigenERP, Source.CentroCostoID, Source.CuentaContable, Source.MontoDOP, Source.FechaContable, SYSDATETIME());

    COMMIT TRANSACTION;
END;
